sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    if (newValue === 'Incident' || newValue === 'incident') {
        alert('IT issues must be reported through the Incident module. Please navigate to the Incident Catalog to log this issue.');

        // 1. Remove mandatory rule first so ServiceNow permits hiding it
        g_form.setMandatory('subcategory', false);

        // 2. Hide and clear the subcategory field
        g_form.setValue('subcategory', '');
        g_form.setDisplay('subcategory', false);

        // 3. Prevent the onChange loop when resetting category
        var controlElem = g_form.getControl('category');
        if (controlElem) {
            controlElem.value = '';
        } else {
            g_form.setValue('category', '');
        }
    } else {
        // Restore for normal categories
        g_form.setDisplay('subcategory', true);
        g_form.setMandatory('subcategory', true);
    }
}
